import { getParentWindow } from "../../utils/getParentWindow";
export const getDefaultProviderMode = (mode) => {
    if (mode) {
        return mode;
    }
    const parent = getParentWindow(window);
    const isTopWindow = window === parent;
    // if initialized in iframe
    if (!isTopWindow) {
        return "api";
    }
    // if "default" Provided already initialized on the same page
    if (parent.document.querySelector(".zen-alerts") || parent.document.querySelector(".zen-toasts")) {
        return "api";
    }
    return "default";
};
